static int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *a = (int *)malloc(sizeof(int) * N);
    int maxA = 0;
    int g = 0;

    for (int i = 0; i < N; i++) {
        scanf("%d", &a[i]);
        if (a[i] > maxA) maxA = a[i];
        g = gcd_int(g, a[i]);
    }

    if (g != 1) {
        printf("not coprime\n");
        free(a);
        return 0;
    }

    int *freq = (int *)calloc(maxA + 1, sizeof(int));
    for (int i = 0; i < N; i++) freq[a[i]]++;

    int pairwise = 1;
    for (int p = 2; p <= maxA; p++) {
        int cnt = 0;
        for (int multiple = p; multiple <= maxA; multiple += p) {
            cnt += freq[multiple];
            if (cnt > 1) {
                pairwise = 0;
                break;
            }
        }
        if (!pairwise) break;
    }

    if (pairwise) {
        printf("pairwise coprime\n");
    } else {
        printf("setwise coprime\n");
    }

    free(freq);
    free(a);
    return 0;
}

