    int g = 0;
    for (int i = 0; i < N; ++i) {
        cin >> a[i];
        mx = max(mx, a[i]);
        g = std::gcd(g, a[i]);
    }

    // If gcd of all numbers is > 1, then neither.
    if (g != 1) {
        cout << "not coprime\n";
        return 0;
    }

    // Check pairwise coprime using prime factor uniqueness.
    vector<int> spf(mx + 1);
    for (int i = 0; i <= mx; ++i) spf[i] = i;
    for (long long i = 2; i * i <= mx; ++i) {
        if (spf[i] == i) {
            for (long long j = i * i; j <= mx; j += i) {
                if (spf[j] == j) spf[j] = (int)i;
            }
        }
    }

    vector<bool> used(mx + 1, false);

    for (int x : a) {
        int y = x;
        vector<int> primes;
        while (y > 1) {
            int p = spf[y];
            primes.push_back(p);
            while (y % p == 0) y /= p;
        }

        for (int p : primes) {
            if (used[p]) {
                cout << "setwise coprime\n";
                return 0;
            }
            used[p] = true;
        }
    }

    cout << "pairwise coprime\n";
    return 0;
}

