import sys
import math

def solve():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    arr = list(map(int, input_data[1:]))

    # Check overall GCD
    overall_gcd = arr[0]
    for num in arr[1:]:
        overall_gcd = math.gcd(overall_gcd, num)
    if overall_gcd != 1:
        print("not coprime")
        return

    # Sieve-like check for shared prime factors
    max_val = max(arr)
    factor_count = [0] * (max_val + 1)

    for num in arr:
        temp = num
        p = 2
        while p * p <= temp:
            if temp % p == 0:
                factor_count[p] += 1
                while temp % p == 0:
                    temp //= p
            p += 1 if p == 2 else 2  # skip even numbers after 2
        if temp > 1:
            factor_count[temp] += 1

    for count in factor_count:
        if count > 1:
            print("setwise coprime")
            return

    print("pairwise coprime")

