public class Main {
    static final int MAX_A = 1000000;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        int[] arr = new int[n];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(st.nextToken());
        }

        // Check setwise coprime
        int g = arr[0];
        for (int i = 1; i < n; i++) {
            g = gcd(g, arr[i]);
        }
        if (g != 1) {
            System.out.println("not coprime");
            return;
        }

        // Check pairwise coprime using smallest prime factor sieve
        int[] spf = new int[MAX_A + 1];
        for (int i = 2; i <= MAX_A; i++) {
            if (spf[i] == 0) {
                for (int j = i; j <= MAX_A; j += i) {
                    if (spf[j] == 0) spf[j] = i;
                }
            }
        }

        boolean[] seen = new boolean[MAX_A + 1];
        for (int x : arr) {
            int temp = x;
            Set<Integer> primes = new HashSet<>();
            while (temp > 1) {
                int p = spf[temp];
                primes.add(p);
                temp /= p;
            }
            for (int p : primes) {
                if (seen[p]) {
                    System.out.println("setwise coprime");
                    return;
                }
                seen[p] = true;
            }
        }

        System.out.println("pairwise coprime");
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int[] a = new int[N];
        int maxA = 0;
        int g = 0;

        for (int i = 0; i < N; i++) {
            a[i] = fs.nextInt();
            maxA = Math.max(maxA, a[i]);
            g = gcd(g, a[i]);
        }

        if (g != 1) {
            System.out.println("not coprime");
            return;
        }

        int[] freq = new int[maxA + 1];
        for (int x : a) freq[x]++;

        boolean pairwise = true;

        // Sieve-like check:
        // if some prime p divides at least two numbers, then not pairwise coprime.
        for (int i = 2; i <= maxA; i++) {
            int count = 0;
            for (int j = i; j <= maxA; j += i) {
                count += freq[j];
                if (count >= 2) {
                    pairwise = false;
                    break;
                }
            }
            if (!pairwise) break;
        }

        if (pairwise) {
            System.out.println("pairwise coprime");
        } else {
            System.out.println("setwise coprime");
        }
    }
}
